from decimal import *
for mode in [ROUND_HALF_EVEN,ROUND_HALF_UP,ROUND_HALF_DOWN,ROUND_UP,ROUND_DOWN,ROUND_CEILING,ROUND_FLOOR,ROUND_05UP]:
 with localcontext() as c:
  c.rounding=mode
  for raw in ['2.55','-2.55','1.01','-1.01','5.00','-0.00','70000000000000000000000000000']:
   for quantum in ['1','0.1','1E+1']:
    c.clear_flags()
    try: result=str(Decimal(raw).quantize(Decimal(quantum)))
    except DecimalException as e: result=type(e).__name__
    print(mode,raw,quantum,result,c.flags[Inexact],c.flags[Rounded],c.flags[InvalidOperation])

from decimal import *
with localcontext() as c:
 c.prec=2;c.rounding=ROUND_FLOOR
