from decimal import *
for precision in [1,3,28]:
 for mode in [ROUND_HALF_EVEN,ROUND_UP,ROUND_DOWN,ROUND_FLOOR]:
  with localcontext() as c:
   c.prec=precision;c.rounding=mode
   for a,b in [('1.234','0.006'),('1.00','-1.00'),('-0.00','0.0'),('1E+2','1E+2'),('60000000000000000000000000000','0.1'),('1.234567890123456789012345678','1.234567890123456789012345678')]:
    x=Decimal(a);y=Decimal(b)
    for name in ['add','subtract','multiply']:
     if name=='multiply' and a=='60000000000000000000000000000': continue
     c.clear_flags()
     v=x+y if name=='add' else x-y if name=='subtract' else x*y
     print(precision,mode,a,b,name,str(v),c.flags[Inexact],c.flags[Rounded])
